INSERT INTO `guide` (`id`, `order`, `judul`, `desc`, `img`, `created_at`, `updated_at`, `deleted_at`) VALUES
('0acd1299-1c6e-4393-b34f-8fa5c7e733b2', 13, '<strong style=\"color: #03346E;\">Ayo Naik Peringkat!</strong>', 'Leaderboard dihitung dari <strong style=\"color: #03346E;\">total poin</strong> + <strong style=\"color: #03346E\">total langkah</strong> drag &amp; drop.\n\n<br>\nRaih posisi teratas dengan poin terbanyak dan langkah paling efisien saat menyusun algoritma!.', 'assets/media/guide_image/guide_68e54a7f34a669.00226842.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('2e46aba8-a46f-41cc-81ab-34df63bbbf9e', 7, '<strong style=\"color: #03346E;\">Rute Belajar</strong>', 'Tiap <strong style=\"color: #000;\">Level</strong> berisi beberapa <strong style=\"color: #000;\">Soal</strong> yang harus dikerjakan<br> \n                        <strong style=\"color: #000;\">secara urut</strong>. Mulai dari soal <strong style=\"color: #F39C12\">Pseudocode</strong> disisi kiri yang berwarna <strong style=\"color: #F39C12\">orange </strong>kemudian dilanjut dengan soal \n                        <strong style=\"color: #03346E;\">Konversi Program</strong> di sisi kanan yang berwarna <strong style=\"color: #03346E;\">biru</strong>.', 'assets/media/guide_image/guide_68e54a7f309db0.01285373.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('575d0b43-a7dc-4954-8914-1247290baead', 8, '<strong style=\"color: #03346E;\">Arena Ujian Pseudocode</strong>', 'Susun algoritma dan tipe data yang telah diacak menjadi<br>urutan yang benar! \n                        lalu klik <strong style=\"color: #03346E;\">\"Cek Jawaban\"</strong> untuk melihat hasilnya.', 'assets/media/guide_image/guide_68e54a7f31fba5.29856768.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('716edd47-0924-40f9-acad-c600dc59c359', 10, '<strong style=\"color: #03346E;\">Kumpulkan AlgoBadge Sebanyak-banyaknya!</strong>', 'Selesaikan setiap soal dan dapatkan <strong style=\"color: #03346E;\">Algobadge</strong>', 'assets/media/guide_image/guide_68e54a7f3301e8.54701010.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('836d3b15-adc0-4e27-b296-a6c90152c034', 4, '<strong style=\"color: #03346E;\">Isi ulang nyawa dengan cepat!</strong>', 'Mau lebih cepat isi ulang nyawa? Selesaikan misi dan klaim hadiahnya!', 'assets/media/guide_image/guide_68e54a7f2e24b6.72470792.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('969fc899-bf0a-4daf-a602-872a89f83a76', 6, '<strong style=\"color: #03346E;\">Buka Kunci Levelmu!</strong>', 'Semua level materi ada di halaman <strong style=\"color: #03346E;\">“Latihan Soal”</strong>\n<br>Setiap level harus dikerjakan berurutan untuk membuka jalan ke level selanjutnya.</p>', 'assets/media/guide_image/guide_68e54a7f2f2375.76145302.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('a25e30ad-a3c6-4afa-89e8-c169869405ba', 5, '<strong style=\"color: #03346E;\">Hati-hati dalam menjawab!</strong>', 'Pikirkan baik-baik sebelum klik <strong style=\"color: #03346E;\">“Cek Jawaban”</strong> karena ketika jawaban salah = 1 nyawa melayang!', 'assets/media/guide_image/guide_68e54a7f2e35b3.86491362.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('abd3a769-a814-4ce7-82a9-2023337ab8f2', 9, '<strong style=\"color: #03346E;\">Arena Ujian Code Program</strong>', 'Ketikan code program sesuai dengan urutan langkah<strong style=\"color: #03346E;\"> algoritma pseudocode!</strong>\n                        lalu klik <strong style=\"color: #03346E;\">“Cek Jawaban”</strong>untuk melihat hasilnya.', 'assets/media/guide_image/guide_68e54a7f32c906.84988560.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('b5bf21cc-f420-410d-8134-9ba16fb5bdd6', 11, '<strong style=\"color: #03346E;\">Dapatkan Algopoin!</strong>', 'Selesaikan semua soal kemudian dapat <strong style=\"color: #03346E\">Algopoin</strong>', 'assets/media/guide_image/guide_68e54a7f331735.74608181.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('bc4e97ef-887b-4deb-9c91-c1ba04a068d4', 2, '<strong style=\"color: #03346E;\">Ini arena progres belajarmu!</strong>', 'kamu bisa melihat total poin, badge yang berhasil diraih,<br>peringkatmu di leaderboard, dan jumlah nyawa yang<br>kamu miliki untuk melanjutkan petualangan belajar!!', 'assets/media/guide_image/guide_68e54a7f2dccc0.14645952.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('c01b34e7-89bf-4b57-bb19-a2a01825f940', 12, 'Lanjut ke Level Selanjutnya!', 'Semua soal berhasil terselesaikan, <strong style=\"color: #03346E\">Level</strong> berikutnya terbuka!', 'assets/media/guide_image/guide_68e54a7f3402b2.52775019.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('cd847477-0a48-4c14-b001-b4d21ee7b2b5', 1, '<strong style=\"color: #F39C12;\">Selamat Datang,</strong> <strong style=\"color: #03346E;\">di <i>PseudoLearn!</i></strong>', 'Yuk, belajar <strong style=\"color: #03346E;\">algoritma</strong>, <strong style=\"color: #03346E;\">tipe data</strong>, dan <strong style=\"color: #03346E;\">Code Program Java</strong>  dengan cara yang seru dan penuh tantangan!', 'assets/media/guide_image/guide_68e54a7f1a5a40.83068755.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL),
('e982aa13-cb7c-4833-82fe-2e288101bce0', 3, '<strong style=\"color: #03346E;\">Hati-hati, Nyawamu Terbatas!</strong>', 'Kamu <strong style=\"color: #03346E\">maksimal</strong> memiliki <strong style=\"color: #03346E;\">25</strong> nyawa. Jika nyawamu hangus, satu nyawa akan otomatis kembali setiap 10 menit.', 'assets/media/guide_image/guide_68e54a7f2df1a9.89356015.png', '2025-10-07 17:14:39', '2025-10-07 17:14:39', NULL);
