INSERT INTO `konversi` (`id`, `id_level`, `id_soal`, `jawaban`, `output`, `bobot`, `created_at`, `updated_at`, `deleted_at`) VALUES
('0199651d-b77a-7329-8b9a-0e5b6b2f16d6', '01995dec-678e-70cf-854a-b25e2c2d0d28', '01995df6-35ed-7363-9d42-578622c3e4f2', '[{\"1\": \"double pajak = 0.1;\"}, {\"2\": \"int harga_motor = 25000000;\"}, {\"3\": \"int uang_bayar;\"}, {\"4\": \"float pajak_jual;\"}, {\"5\": \"pajak_jual = pajak * harga_motor;\"}, {\"6\": \"uang_bayar = harga_motor + pajak_jual;\"}, {\"7\": \"System.out.print(uang_bayar);\"}]', '27500000', 100, '2025-09-20 03:14:30', '2025-10-02 05:41:45', NULL),
('01996525-5cf1-7256-8f2f-184909a171ff', '01995dec-678e-70cf-854a-b25e2c2d0d28', '01995e0a-74d3-73fa-895b-cfe6f4ec6ab6', '[{\"1\": \"int harga_dasar;\"}, {\"2\": \"float persentase_pajak;\"}, {\"3\": \"int harga_akhir;\"}, {\"4\": \"float nilai_pajak;\"}, {\"5\": \"harga_dasar = 85000;\"}, {\"6\": \"persentase_pajak = 0.1;\"}, {\"7\": \"nilai_pajak = harga_dasar * persentase_pajak;\"}, {\"8\": \"harga_akhir = harga_dasar + nilai_pajak;\"}, {\"9\": \"System.out.print(\\\"Harga akhir setelah pajak: Rp\\\" + harga_akhir);\"}]', 'Harga akhir setelah pajak: Rp93500', 100, '2025-09-20 03:22:51', '2025-10-02 05:40:16', NULL),
